const { auth, bundles } = require('../../../services/index');
const money = cents => (Number(cents || 0) / 100).toFixed(2);
Page({
  data: { id: '', status: 'loading', errorText: '', bundle: null, quantity: 1, quote: null, quoting: false },
  onLoad(query = {}) { this.setData({ id: query.id ? decodeURIComponent(query.id) : '' }); return this.load(); },
  async load() { if (!this.data.id) return this.setData({ status: 'empty', errorText: '套餐编号无效' }); this.setData({ status: 'loading', errorText: '' }); const result = await bundles.get({ id: this.data.id }); const source = result && result.ok && result.data && (result.data.bundle || result.data); if (!source) return this.setData({ status: result && result.error && result.error.code === 'BUNDLE_NOT_FOUND' ? 'empty' : 'error', errorText: result && result.error && result.error.message || '套餐详情加载失败' }); const quantity = Math.max(1, Number(source.minQuantity || 1)); this.setData({ status: 'ready', quantity, bundle: { ...source, id: source._id || this.data.id, name: source.name || source.title || '采购套餐', description: source.description || '', items: (result.data.items || source.items || []).map(item => ({ ...item, name: item.productName || item.name || '套餐商品', spec: item.specName || item.spec || '', quantity: Number(item.quantity || 0) })) } }); const me = await auth.getMe(); if (!me || !me.ok || !me.data || !me.data.user) return this.setData({ quote: null, errorText: '登录后可核验套餐价格并进入结算' }); return this.loadQuote(); },
  retry() { return this.load(); },
  changeQty(event) { const step = Number(event.currentTarget.dataset.step || 0); const min = Math.max(1, Number(this.data.bundle && this.data.bundle.minQuantity || 1)); this.setData({ quantity: Math.max(min, this.data.quantity + step), quote: null }, () => this.loadQuote()); },
  async loadQuote() { this.setData({ quoting: true }); const result = await bundles.quote({ bundleId: this.data.id, quantity: this.data.quantity }); const quote = result && result.ok && result.data && (result.data.quote || result.data); this.setData({ quoting: false, quote: quote ? { total: money(quote.payableAmountCent === undefined ? quote.totalAmountCent : quote.payableAmountCent), goods: money(quote.goodsAmountCent), snapshot: quote.bundleSnapshot || null } : null, errorText: quote ? '' : result && result.error && result.error.message || '套餐报价暂时无法核验' }); },
  async buy() { const me = await auth.getMe(); if (!me || !me.ok || !me.data || !me.data.user) return wx.showToast({ title: '请先登录后购买套餐', icon: 'none' }); if (!this.data.quote) return wx.showToast({ title: '请先完成服务端报价核验', icon: 'none' }); wx.navigateTo({ url: `/package-trade/pages/checkout/index?bundleId=${encodeURIComponent(this.data.id)}&bundleQuantity=${this.data.quantity}` }); },
  back() { wx.navigateBack(); }
});
